using System;using System.IO;using System.Linq;using System.Reflection;using System.Windows;using System.Windows.Media;using System.Xml.Linq;
class RestartQA {
 static Type panelType=typeof(GridNest.PanelWindow);static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool result,string text){if(!result)throw new Exception(text);}
 static XElement Profile(){return new XElement("Panel",new XAttribute("Columns",6),new XAttribute("Rows",3),new XAttribute("Width",464),new XAttribute("Height",286),new XAttribute("Left",64),new XAttribute("Top",64),new XAttribute("IconSize",56),new XAttribute("Opacity",.5),new XAttribute("Background","#24425C"),new XAttribute("OutlineColor","#B8E1E4"),new XAttribute("OutlineThickness",2),new XAttribute("OutlineGlow",75),new XAttribute("GlowMode","Both"));}
 static void Loaded(GridNest.PanelWindow p){panelType.GetField("loaded",flags).SetValue(p,true);}
 static GridNest.PanelWindow Panel(string name){var p=new GridNest.PanelWindow(name,0);GridNest.Program.Panels.Add(p);return p;}
 static void Verify(GridNest.PanelWindow p){Check((Color)panelType.GetField("background",flags).GetValue(p)==Color.FromRgb(36,66,92),"Background reset");Check((double)panelType.GetField("alpha",flags).GetValue(p)==.5,"Opacity reset");Check((int)panelType.GetField("columns",flags).GetValue(p)==6,"Grid reset");Check((double)panelType.GetField("outlineGlow",flags).GetValue(p)==75,"Glow reset");}
 [STAThread]static void Main(string[] args){
  var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};string root=args.Length==2?Path.GetFullPath(args[1]):Path.Combine(Path.GetTempPath(),"GridNest-settings-restart-"+Guid.NewGuid().ToString("N"));GridNest.Program.Data=root;GridNest.Program.Home=Path.Combine(root,".app");Directory.CreateDirectory(GridNest.Program.Home);GridNest.Program.ApplyAppearance();string path=Path.Combine(GridNest.Program.Home,"Игры.xml");var desired=Profile();if(args.Length==2){if(args[0]=="--seed")desired.Save(path);var instance=Panel("Игры");Verify(instance);Loaded(instance);instance.Save();instance.Close();app.Shutdown();Console.WriteLine("PASS settings retained in separate process");return;}desired.Save(path);GridNest.PanelWindow blocked;
  using(var locked=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){blocked=Panel("Игры");}Loaded(blocked);blocked.Save();bool unchanged=XNode.DeepEquals(desired,XElement.Load(path));
  if(args.Length>0&&args[0]=="--baseline"){Console.WriteLine(unchanged?"No reset reproduced":"REPRODUCED: temporary read failure overwrites custom games settings with defaults");blocked.Close();app.Shutdown();return;}
  Check(unchanged,"Temporary read failure overwrote settings");blocked.Close();Check(XNode.DeepEquals(desired,XElement.Load(path)),"Closing unreadable panel overwrote settings");
  var p=Panel("Игры");Verify(p);Loaded(p);p.Save();Check(File.Exists(path+".bak"),"Backup missing");Verify(p);p.Close();
  for(int i=0;i<3;i++){var restarted=Panel("Игры");Verify(restarted);Loaded(restarted);restarted.Save();restarted.Close();Check((string)XElement.Load(path).Attribute("Background")=="#24425C","Restart persistence");}
  File.WriteAllText(path,"<Panel Background=\"");var recovered=Panel("Игры");Verify(recovered);Loaded(recovered);recovered.Save();recovered.Close();Check((string)XElement.Load(path).Attribute("Background")=="#24425C","Backup recovery failed");Check((string)XElement.Load(path+".bak").Attribute("Background")=="#24425C","Good backup replaced by damaged XML");
  File.WriteAllText(path,"broken primary");File.WriteAllText(path+".bak","broken backup");var corrupt=Panel("Игры");Loaded(corrupt);corrupt.Save();corrupt.Close();Check(File.ReadAllText(path)=="broken primary"&&File.ReadAllText(path+".bak")=="broken backup","Damaged settings destroyed");
  desired.Save(path);desired.Save(path+".bak");using(var locked=new FileStream(path,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){var fallback=Panel("Игры");Verify(fallback);Loaded(fallback);fallback.Save();fallback.Close();}Check((string)XElement.Load(path).Attribute("Background")=="#24425C","Locked save damaged original");
  File.Delete(path);var missing=Panel("Игры");Verify(missing);Loaded(missing);missing.Save();missing.Close();Check(File.Exists(path),"Missing primary not restored from backup");
  Console.WriteLine("PASS temporary read failure without data loss; repeated restarts; atomic save and backups; damaged primary recovery; corrupt files retained; locked write retained; missing primary recovery");app.Shutdown();
 }
}
